Method.Source:
    /// <summary>
    /// Error message
    /// </summary>
    /// <param name = "_value">Error Message</param>
    /// <returns>Returns error message in string format</returns>
    [DataMember("Error Message")]
    public str parmErrorMessage(str _value = errMessage)
    {
        if(!prmIsDefault(_value))
        {
            errMessage = _value;
        }

        return errMessage;
    }

    /// <summary>
    /// Success message
    /// </summary>
    /// <param name = "_value">Success Message</param>
    /// <returns>Return success message - True or False</returns>
    [DataMember("Success")]
    public boolean parmSuccess(boolean _value = success)
    {
        if(!prmIsDefault(_value))
        {
            success = _value;
        }

        return success;
    }
